import java.util.Scanner;

public class EmailObfuscator {
    public static int searchForSubstring(String s, String pattern, int startPos) {
        for (int i = startPos; i <= s.length() - pattern.length(); i++) {
            if (s.charAt(i) == pattern.charAt(0)) {
                boolean matchFound = true;
                for (int j = 1; j < pattern.length(); j++) {
                    if (s.charAt(i + j) != pattern.charAt(j)) {
                        matchFound = false;
                        break;
                    }
                }
                if (matchFound) return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String emailInput = scanner.nextLine();
        int atPos = searchForSubstring(emailInput, "at", 1);
        String tempStr = emailInput.substring(0, atPos) + '@' + emailInput.substring(atPos + 2);
        int dotPos = searchForSubstring(tempStr, "dot", 1);
        StringBuilder finalOutput = new StringBuilder();
        int lastPos = 0;
        while (dotPos != -1 && dotPos < tempStr.length() - 3) {
            finalOutput.append(tempStr.substring(lastPos, dotPos)).append(".");
            lastPos = dotPos + 3;
            dotPos = searchForSubstring(tempStr, "dot", lastPos);
        }
        finalOutput.append(tempStr.substring(lastPos));
        System.out.println(finalOutput.toString());
        scanner.close();
    }
}
